import java.util.Scanner;
public class RailFenceCipher {static String enc(String s,int r){if(r<=1)return s;StringBuilder[] a=new StringBuilder[r];for(int i=0;i<r;i++)a[i]=new StringBuilder();int row=0,d=1;for(char c:s.toCharArray()){a[row].append(c);if(row==0)d=1;else if(row==r-1)d=-1;row+=d;}StringBuilder o=new StringBuilder();for(StringBuilder b:a)o.append(b);return o.toString();}static String dec(String s,int r){if(r<=1)return s;int n=s.length();int[] rows=new int[n];int row=0,d=1;for(int i=0;i<n;i++){rows[i]=row;if(row==0)d=1;else if(row==r-1)d=-1;row+=d;}char[] out=new char[n];int k=0;for(int rr=0;rr<r;rr++)for(int i=0;i<n;i++)if(rows[i]==rr)out[i]=s.charAt(k++);return new String(out);}public static void main(String[]z){Scanner sc=new Scanner(System.in);System.out.print("Enter plaintext: ");String p=sc.nextLine().replace(" ","");System.out.print("Enter number of rails: ");int r=sc.nextInt();if(r<1){System.out.println("Rails must be positive.");return;}String c=enc(p,r);System.out.println("Ciphertext: "+c);System.out.println("Decrypted: "+dec(c,r));}}
